(()=>{const root=document.documentElement,system=window.matchMedia('(prefers-color-scheme: dark)');let preference='system';try{preference=localStorage.getItem('appearance')||'system';}catch{}if(!['system','light','dark'].includes(preference))preference='system';const apply=()=>{root.dataset.theme=preference==='system'?(system.matches?'dark':'light'):preference;};apply();system.addEventListener('change',apply);const control=document.getElementById('appearance');if(control){control.value=preference;control.addEventListener('change',()=>{preference=control.value;try{localStorage.setItem('appearance',preference);}catch{}apply();});}})();